package com.sumedha.commerce.user.service;
import com.sumedha.commerce.user.dto.request.CreateProfileRequest; import com.sumedha.commerce.user.entity.UserPreference; import com.sumedha.commerce.user.entity.UserProfile; import com.sumedha.commerce.user.repository.*; import com.sumedha.commerce.common.core.exception.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class UserProfileServiceImplTest {@Mock UserProfileRepository profiles;@Mock AddressRepository addresses;@Mock UserPreferenceRepository preferences;UserProfileService service;UUID id;@BeforeEach void set(){service=new UserProfileServiceImpl(profiles,addresses,preferences);id=UUID.randomUUID();}@Test void createsProfileAndDefaults(){when(profiles.save(any())).thenAnswer(i->i.getArgument(0));var r=service.create(id,new CreateProfileRequest("Ada","Love","1","url",null));assertEquals(id,r.authUserId());verify(preferences).save(any(UserPreference.class));}@Test void rejectsDuplicateAndMissing(){when(profiles.existsByAuthUserId(id)).thenReturn(true);assertThrows(ConflictException.class,()->service.create(id,new CreateProfileRequest("A","B",null,null,null)));when(profiles.findByAuthUserId(id)).thenReturn(Optional.empty());assertThrows(ResourceNotFoundException.class,()->service.get(id));}}
